using System;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class PopulationChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  foreach(int count in new[]{3,6}){
   var state=new SliceState{resources=new ResourceState{wheat=7,wood=11},tools=new ToolTechnologyState(),families=new FamilyState(),relationships=VillagePopulation.Create(VillagePopulation.Social)};
   Array.Resize(ref state.resources.cargo,count);Array.Resize(ref state.tools.learners,count);Array.Resize(ref state.families.adults,count);Array.Resize(ref state.relationships,count);
   state.relationships[count-1].trust=.91f;for(int i=0;i<3;i++)state.tools.Practice(0,1);state.resources.resin=3;Require(state.tools.Craft(state.resources,0,VillageTool.BoundAxe),"Cannot stage legacy tool");state.resources.Ensure("legacy-tree",VillageResource.Wood);state.resources.Harvest(count-1,"legacy-tree",3);Require(state.Valid(),"Legacy roster rejected: "+count);
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state));Require(saved.Valid(),"Legacy round trip failed");var oldActor=saved.relationships[count-1];var oldCargo=saved.resources.cargo[count-1];var oldTraits=saved.families.adults[count-1];saved.Social(11);var resources=saved.Resources;var tools=saved.Tools;var family=saved.Families;
   Require(saved.relationships.Length==12&&resources.cargo.Length==12&&tools.learners.Length==12&&family.adults.Length==12&&saved.Valid(),"Migration did not safely expand records");Require(saved.relationships[count-1]==oldActor&&oldActor.trust==.91f&&resources.cargo[count-1]==oldCargo&&oldCargo.amount==3&&family.adults[count-1]==oldTraits&&tools.learners[0].axeOwned&&resources.wheat==7&&resources.wood==9,"Migration overwrote original progress");Require(!tools.learners[11].axeOwned&&resources.cargo[11].amount==0,"Migration granted free equipment/cargo");
   for(int i=0;i<3;i++)tools.Practice(11,2);Require(tools.learners[11].hoeKnown&&tools.Craft(resources,11,VillageTool.CultivatingHoe)&&tools.Valid(),"Twelfth villager cannot learn/craft independently");Require(family.FormHousehold(10,11,10)&&family.Valid(),"New identities cannot form a household");family.bond=.9f;family.clock=300;Require(family.TryBirth(10,1)&&family.children[0].parentA==10&&family.children[0].parentB==11&&family.Valid(),"New parent identities lost lineage");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(saved)).Valid(),"Twelve-adult save invalid");
   var corrupt=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(saved));Array.Resize(ref corrupt.resources.cargo,4);Require(!corrupt.Valid(),"Unexpected roster length accepted");
  }
  var food=new ResourceState{wheat=48};food.Consume(90,15);Require(food.wheat==33&&food.consumed==15&&VillageResources.ReserveTarget(15,72)==63,"Food demand did not count fifteen residents");
  var oldFamily=new FamilyState();Array.Resize(ref oldFamily.adults,6);oldFamily.FormHousehold(4,5,2);oldFamily.bond=.9f;oldFamily.clock=300;oldFamily.TryBirth(10,1);oldFamily.EnsurePopulation();Require(oldFamily.Valid()&&oldFamily.parentA==4&&oldFamily.parentB==5&&oldFamily.children[0].parentB==5,"Existing family lineage lost on expansion");
  var opinions=VillagePopulation.Create(VillagePopulation.Social);for(int i=0;i<6;i++)opinions[i].trust=.9f;Require(TributeMemory.Consensus(opinions)==TributeMotive.None,"Half village counted as majority");opinions[6].trust=.9f;Require(TributeMemory.Consensus(opinions)==TributeMotive.Affection,"Seven of twelve did not count as majority");Debug.Log("BWVR_POPULATION_MODEL_PASS: three/six migration, twelfth learner/crafter, parent lineage, fifteen-person food and bounded saves");
 }
 [MenuItem("BWVR/Verify expanded village population (Play mode)")]
 public static void Verify(){VerifyModel();Require(Application.isPlaying,"Enter Play mode");var w=UnityEngine.Object.FindAnyObjectByType<VillageResources>();Require(w.Gatherers.Length==12,"Starting village does not have twelve adults");var ids=w.Gatherers.Select(a=>a.GetComponent<VillagerIdentity>()).ToArray();Require(ids.All(i=>i!=null)&&ids.Select(i=>i.Index).Distinct().Count()==12&&ids.Count(i=>i.Gender==VillagerGender.Man)==6&&ids.Count(i=>i.Gender==VillagerGender.Woman)==6,"Roster identity or gender balance invalid");
  foreach(var actor in w.Gatherers){var id=actor.GetComponent<VillagerIdentity>().Index;var animator=actor.GetComponentInChildren<Animator>();Require(animator!=null&&animator.isHuman&&animator.avatar.isValid,"Missing rig for actor "+id);Require(actor.GetComponent<HybridTarget>().id=="villager-"+id&&actor.GetComponent<VillagerAffect>()!=null,"Missing stable target or affect icon");Require(Enum.IsDefined(typeof(VillagerRoutine.Role),actor.GetComponent<VillagerRoutine>().role),"Invalid job role");Require(w.Season.Social(id).Valid(),"Invalid personal social memory");}
  var discoveries=w.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>();var point=discoveries.points[0];int visitors=point.Record.visitors;try{point.Record.visitors=0;Require(point.Unseen(12)&&point.Discover(12)&&!point.Discover(12)&&!point.Unseen(13)&&point.Record.visitors==4096&&w.Season.Valid(),"Newcomer discovery identity or save mask invalid");}finally{point.Record.visitors=visitors;}
  var god=w.GetComponentInParent<QuestSlice>().GetComponentInChildren<CreatureHybrid>();Require(god.Find("object-3")?.affordance?.kind==CreatureAffordance.Kind.Food&&god.Find("water")!=null,"Legacy food/water target lost");Require(god.Find("resource-5")!=null,"Legacy wood target lost");
  Require(w.Gatherers.Count(a=>a.GetComponent<VillagerRoutine>().role==VillagerRoutine.Role.WaterGatherer)==1,"Expansion multiplied water jobs");Require(w.Season.Resources.cargo.Length==12&&w.Season.Tools.learners.Length==12&&w.Season.Families.adults.Length==12&&w.Season.Valid(),"Live population state incomplete");Debug.Log("BWVR_POPULATION_RUNTIME_PASS: twelve humanoid adults, six men/six women, stable IDs, icons, one water job, complete saved records");
 }
}
}
